import re
p='app/api/v3/tags/lib/schemas.ts'
s=open(p).read()
s=s.replace('export const ZV3TagListQuery = z.object({ workspaceId: z.cuid2() }).strict();\n',
'export const ZV3TagListQuery = z.object({ workspaceId: z.cuid2() }).strict();\n\nexport const ZV3DeleteUnusedTagsQuery = z.object({ workspaceId: z.cuid2() }).strict();\n',1)
s=s.replace('export type TV3TagListQuery = z.infer<typeof ZV3TagListQuery>;\n',
'export type TV3TagListQuery = z.infer<typeof ZV3TagListQuery>;\nexport type TV3DeleteUnusedTagsQuery = z.infer<typeof ZV3DeleteUnusedTagsQuery>;\n',1)
open(p,'w').write(s)

p='app/api/v3/tags/lib/operations.ts'
s=open(p).read()
s=s.replace('import { deleteTag, mergeTags, updateTagName } from "@/modules/workspaces/settings/lib/tag";',
'import { deleteTag, deleteUnusedTags, mergeTags, updateTagName } from "@/modules/workspaces/settings/lib/tag";',1)
s=s.rstrip('\n')+'''

export async function deleteUnusedV3Tags(
  params: TBaseParams & { workspaceId: string; auditLog?: TV3AuditLog }
): Promise<Response> {
  const { workspaceId, auditLog, requestId, instance } = params;

  const access = await requireV3WorkspaceAccess(params.authentication, workspaceId, "readWrite", requestId, instance);
  if (access instanceof Response) return access;

  if (auditLog) {
    auditLog.organizationId = access.organizationId;
    auditLog.targetId = workspaceId;
  }

  const result = await deleteUnusedTags(workspaceId);
  if (!result.ok) {
    return problemInternalError(requestId, "Unable to delete unused tags", instance);
  }

  if (auditLog) auditLog.oldObject = { workspaceId, deletedCount: result.data.count };

  return successResponse({ deletedCount: result.data.count }, { requestId });
}
'''
open(p,'w').write(s)
