mkdir -p "app/api/v3/tags/delete-unused" && cat > "app/api/v3/tags/delete-unused/route.ts" <<'EOF'
/**
 * POST /api/v3/tags/delete-unused — delete every tag in a workspace that no response carries.
 *
 * A POST custom method rather than a `DELETE` on the collection, for the same reason as
 * `responses/batch-delete`: a collection-level delete that loses its scope must not be reachable by
 * accident. Session-only, matching the tag routes it sits beside.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { deleteUnusedV3Tags } from "../lib/operations";
import { ZV3DeleteUnusedTagsQuery } from "../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "session",
  action: "deleted",
  targetType: "tag",
  schemas: { query: ZV3DeleteUnusedTagsQuery },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    deleteUnusedV3Tags({
      authentication,
      workspaceId: parsedInput.query.workspaceId,
      auditLog,
      requestId,
      instance,
    }),
});
EOF
